WITH RECURSIVE x10(x11) AS (SELECT 1 AS x19, 'G' AS x20, 40 AS x21 UNION SELECT 2, 'G', 60 UNION SELECT 3, 'S', 60 UNION SELECT 4, 'S', 20) SELECT x7.v226526, x7.v226526, x7.v226526 AS x4, x7.v226526 FROM v226525 AS x7 WHERE x7.v226526 BETWEEN SUBTIME('0000-00-00', '00:00:00') AND x7.v226526 AND x7.v226526 = STR_TO_DATE(DATE_FORMAT(TIME('00:00:00.000000'), CONCAT_WS('-', '%s', '%k')), CONCAT_WS(':', '%i', '%i')) AND x7.v226526 BETWEEN UNIX_TIMESTAMP('0000-00-00 00:00:00') AND x7.v226526 AND NOT x7.v226526 IS NULL